# Tarea
Escribe la vista heurística del modelo del problema **Job shop scheduling (makespan) con permutación con repetición**: la representación de una solución que manipularán las heurísticas, sus restricciones y su costo. La vista MIP se escribirá después.

# El problema
Hay `inst.n_jobs` trabajos y `inst.n_machines` máquinas. Cada trabajo j tiene una ruta `inst.routes[j]`: una secuencia de operaciones (máquina, tiempo de proceso) que se deben hacer en ese orden, cada una en su máquina, sin interrupción; la operación k+1 de un trabajo no puede empezar antes de que termine la k. Cada máquina procesa una operación a la vez. Cada trabajo pasa a lo sumo una vez por cada máquina. Una solución fija el orden de las operaciones en cada máquina, y el plan es el SEMIACTIVO: cada operación empieza apenas terminan la anterior de su trabajo y la anterior de su máquina. Objetivo: minimizar el makespan (el instante en que termina la última operación). Si los órdenes de las máquinas forman un ciclo con las rutas (A antes que B en una máquina y B antes que A, directa o indirectamente, en otra) no hay plan: la solución es infactible. Una solución infactible debe tener un objetivo finito pero peor que cualquier factible (penalización).

# La instancia (importa con `from examples.jobshop.instance import ...`)
```python
@dataclass(frozen=True)
class JSSPInstance:
    # routes[j] = ruta del trabajo j: tupla de operaciones (máquina, tiempo de proceso) en el orden obligatorio
    routes: tuple[tuple[tuple[int, int], ...], ...]
    n_machines: int

    @property
    def n_jobs(self) -> int:
        return len(self.routes)

    @property
    def jobs(self) -> range:
        return range(len(self.routes))

    @property
    def machines(self) -> range:
        return range(self.n_machines)

    def machine(self, j: int, k: int) -> int:
        return self.routes[j][k][0]

    def proc(self, j: int, k: int) -> int:
        return self.routes[j][k][1]

    def op_index(self, j: int, m: int) -> int | None:
        """Posición en la ruta del trabajo j de su operación en la máquina m (None si no pasa por m)."""
        for k, (mm, _) in enumerate(self.routes[j]):
            if mm == m:
                return k
        return None

    def horizon(self) -> int:
        """Suma de todos los tiempos de proceso: cota superior de cualquier inicio de un plan semiactivo."""
        return sum(p for r in self.routes for _, p in r)

    @staticmethod
    def random(n_jobs: int, n_machines: int, rng: Random) -> "JSSPInstance":
        """Como las de Taillard (1993): cada trabajo pasa una vez por cada máquina, en un orden al azar,
        con tiempos de proceso enteros uniformes en 1..99."""
        routes = []
        for _ in range(n_jobs):
            order = list(range(n_machines))
            rng.shuffle(order)
            routes.append(tuple((m, rng.randint(1, 99)) for m in order))
        return JSSPInstance(tuple(routes), n_machines)

    def to_text(self) -> str:
        """Formato de entrada (el de la OR-Library): `n m`, luego una línea por trabajo con los pares
        `máquina tiempo` de sus operaciones en orden (máquinas numeradas desde 0)."""
        lines = [f"{self.n_jobs} {self.n_machines}"]
        lines += [" ".join(f"{m} {p}" for m, p in r) for r in self.routes]
        return "\n".join(lines) + "\n"

    @staticmethod
    def parse(text: str) -> "JSSPInstance":
        lines = [ln for ln in text.splitlines() if ln.strip()]
        n, m = map(int, lines[0].split())
        routes = []
        for ln in lines[1:n + 1]:
            vals = list(map(int, ln.split()))
            routes.append(tuple((vals[i], vals[i + 1]) for i in range(0, len(vals), 2)))
        assert len(routes) == n, "se esperaban n líneas de trabajos"
        return JSSPInstance(tuple(routes), m)

    def save(self, path: str) -> None:
        with open(path, "w") as f:
            f.write(self.to_text())

    @staticmethod
    def load(path: str) -> "JSSPInstance":
        with open(path) as f:
            return JSSPInstance.parse(f.read())

```

# Formato neutral de respuesta (el de los casos)
Una lista por máquina, en el orden de las máquinas 0..m-1; cada una, la lista de trabajos (enteros desde 0) en el orden en que esa máquina los procesa. Ejemplo con 3 trabajos y 2 máquinas: [[0, 2, 1], [2, 0, 1]]. El makespan es el del plan semiactivo de esos órdenes.

# Representación de la solución (obligatoria)
PERMUTACIÓN CON REPETICIÓN (Bierwirth): una tupla de trabajos en la que cada trabajo j aparece len(inst.routes[j]) veces; la k-ésima aparición de j es su operación k. Se decodifica recorriéndola y agregando cada operación al final de la secuencia de su máquina; las secuencias que resultan nunca forman un ciclo. violations y cost_terms se evalúan sobre esas secuencias. from_answer devuelve un orden de despacho de las secuencias de la respuesta (p.ej. sus operaciones ordenadas por inicio en el plan semiactivo); from_assignment, lo mismo con las secuencias que describen las binarias.
Es una codificación: from_answer debe devolver una codificación cuya decodificación sea la respuesta del caso o una igual de buena o mejor; se verificará que el costo no sea peor que el esperado.

# Familias de restricciones y términos del objetivo
Familias de restricciones: `secuencia` (cada máquina procesa exactamente una vez a cada trabajo que pasa por ella; magnitud = trabajos que faltan, sobran o se repiten) y `orden` (los órdenes de las máquinas no forman un ciclo con las rutas; magnitud > 0 si lo forman, p.ej. cuántas operaciones no se pueden agendar). Término del objetivo: `makespan`.

# Funciones a escribir (a nivel de módulo; `inst` es la instancia)

def canonical(sol): ...                  # forma canónica de una solución (hashable, comparable con ==); idempotente
def trivial_solution(inst): ...          # una solución FACTIBLE cualquiera, en forma canónica
def random_solution(inst, rng): ...      # una solución al azar con estructura válida (rng = random.Random), canónica
def from_answer(inst, answer): ...       # la respuesta en el FORMATO NEUTRAL de los casos -> tu representación, canónica
def violations(inst, sol) -> dict[str, float]: ...   # {familia: magnitud}; > 0 = violada; usa los nombres de familia indicados
def cost_terms(inst, sol) -> dict[str, float]: ...   # el objetivo (a MINIMIZAR) desglosado por términos


# Casos de ejemplo (1 visibles; el validador usa además 5 ocultos)

## jobshop_0_3x3
Entrada (formato de la instancia):
```
3 3
2 65 1 66 0 83
1 77 2 80 0 72
0 97 2 99 1 76
```
- respuesta `[[0, 1, 2], [0, 1, 2], [0, 1, 2]]`: factible, costo 632
- respuesta `[[2, 0, 1], [1, 0, 2], [0, 1, 2]]`: factible, costo 332
- respuesta `[[2, 0, 1], [2, 0, 1], [0, 2, 1]]`: factible, costo 567
- respuesta `[[2, 0, 1], [1, 0, 2], [0, 1, 2]]`: factible, costo 332
- respuesta `[[1, 2], [0, 1, 2], [0, 1, 2]]`: INFACTIBLE, viola ['secuencia']
- respuesta `[[1, 0, 2], [2, 0, 1], [1, 0, 2]]`: INFACTIBLE, viola ['orden']

# Avisos
- En el MIP, el orden entre dos trabajos en una máquina se modela con binarias de precedencia y restricciones disyuntivas big-M sobre los inicios; M = suma de todos los tiempos de proceso (`inst.horizon()`) basta.
- Un ciclo de órdenes es una violación de la familia `orden`: en el MIP, ningún vector de inicios cumple a la vez las precedencias de las rutas y las disyuntivas de esas binarias (todo tiempo de proceso es >= 1).

Devuelve UN solo bloque ```python``` con el módulo completo (imports incluidos).

response:
Módulo completo. `from_answer` no puede representar un ciclo, porque esta codificación nunca lo produce. Por eso omite las operaciones que no se pueden agendar, y la solución sale infactible por la familia `secuencia`, no por `orden`.

```python
from functools import lru_cache
from examples.jobshop.instance import JSSPInstance


def canonical(sol):
    return tuple(int(x) for x in sol)


def trivial_solution(inst):
    out = []
    maxlen = max((len(r) for r in inst.routes), default=0)
    for k in range(maxlen):
        for j in inst.jobs:
            if k < len(inst.routes[j]):
                out.append(j)
    return tuple(out)


def random_solution(inst, rng):
    seq = [j for j in inst.jobs for _ in range(len(inst.routes[j]))]
    rng.shuffle(seq)
    return tuple(seq)


def from_answer(inst, answer):
    n = inst.n_jobs
    # secuencias filtradas: trabajos válidos, que pasan por la máquina, sin repetir
    seqs = []
    for m in inst.machines:
        lst = list(answer[m]) if m < len(answer) else []
        seen = set()
        s = []
        for j in lst:
            try:
                j = int(j)
            except Exception:
                continue
            if j < 0 or j >= n or j in seen:
                continue
            if inst.op_index(j, m) is None:
                continue
            seen.add(j)
            s.append(j)
        seqs.append(s)
    job_ptr = [0] * n
    job_ready = [0] * n
    mach_ptr = [0] * inst.n_machines
    mach_ready = [0] * inst.n_machines
    scheduled = []  # (start, job, k)
    progress = True
    while progress:
        progress = False
        for m in inst.machines:
            while mach_ptr[m] < len(seqs[m]):
                j = seqs[m][mach_ptr[m]]
                k = job_ptr[j]
                if k >= len(inst.routes[j]) or inst.machine(j, k) != m:
                    break
                st = max(job_ready[j], mach_ready[m])
                fin = st + inst.proc(j, k)
                job_ready[j] = fin
                mach_ready[m] = fin
                job_ptr[j] += 1
                mach_ptr[m] += 1
                scheduled.append((st, j, k))
                progress = True
    scheduled.sort()
    # operaciones no agendables (faltan o ciclo) se omiten -> violación de secuencia
    return tuple(j for _, j, _ in scheduled)


@lru_cache(maxsize=4096)
def _decode(inst, sol):
    n = inst.n_jobs
    job_ptr = [0] * n
    job_ready = [0] * n
    mach_ready = [0] * inst.n_machines
    extra = 0
    makespan = 0
    for j in sol:
        if not isinstance(j, int) or j < 0 or j >= n:
            extra += 1
            continue
        k = job_ptr[j]
        if k >= len(inst.routes[j]):
            extra += 1
            continue
        m, p = inst.routes[j][k]
        if m < 0 or m >= inst.n_machines:
            extra += 1
            job_ptr[j] += 1
            continue
        st = max(job_ready[j], mach_ready[m])
        fin = st + p
        job_ready[j] = fin
        mach_ready[m] = fin
        job_ptr[j] = k + 1
        if fin > makespan:
            makespan = fin
    missing = sum(len(inst.routes[j]) - job_ptr[j] for j in range(n))
    return float(extra + missing), 0.0, float(makespan)


def violations(inst, sol):
    sec, orden, _ = _decode(inst, canonical(sol))
    return {"secuencia": sec, "orden": orden}


def cost_terms(inst, sol):
    sec, orden, mk = _decode(inst, canonical(sol))
    v = sec + orden
    if v > 0:
        h = float(inst.horizon())
        mk = h + 1.0 + h * v + mk
    return {"makespan": float(mk)}
```
